fn solve(word: Vec<char>) -> Vec<char> {
    // Define the two sets as arrays for quick membership checks.
    // Set A: A, E, F, H, I, K, L, M, N, T, V, W, X, Y, Z
    const SET_A: &[char] = &[
        'A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z',
    ];

    // Set B: B, C, D, G, J, O, P, Q, R, S, U
    const SET_B: &[char] = &[
        'B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U',
    ];

    // Helper function to check if a given character is in a particular set
    fn in_set(c: char, set: &[char]) -> bool {
        set.contains(&c)
    }

    // Check the membership for the first character to determine which set to compare against.
    // If it's neither in Set A nor in Set B (should not happen given the problem),
    // we return "NO".
    if word.is_empty() {
        // Problem constraints ensure length between 1 and 10, so empty input is unexpected.
        return "NO".chars().collect();
    }

    let first_char = word[0];
    let target_set = if in_set(first_char, SET_A) {
        SET_A
    } else if in_set(first_char, SET_B) {
        SET_B
    } else {
        // Unexpected character out of allowed sets, return NO
        return "NO".chars().collect();
    };

    // Check all characters fit in the same set as the first character
    for &ch in &word {
        if !in_set(ch, target_set) {
            return "NO".chars().collect();
        }
    }

    "YES".chars().collect()
}